// The index of a code point's glyph, or -1 when the faces have none.
inline int glyph_index(unsigned code) {
    int lo = 0, hi = kGlyphs - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        if (kCodes[mid] == code) return mid;
        if (kCodes[mid] < code) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}
